#[tokio::test]
async fn secrets_scenarios_in_memory() {
    let handler = SecretsHandler::new(|| {
        Arc::new(InMemorySecretsProvider::new()) as Arc<dyn SecretsProvider>
    });
    assert!(format!("{handler:?}").contains("SecretsHandler"));
    let report = runner(handler).run().await.unwrap();
    report.assert_success();
    assert!(report.passed() >= 4, "{report}");
    for id in [
        "secrets.roundtrip",
        "secrets.bulk",
        "secrets.missing",
        "secrets.redaction",
    ] {
        assert_eq!(
            report.result(id).map(|r| &r.status),
            Some(&ScenarioStatus::Passed),
            "{id}"
        );
    }
}

#[tokio::test]
