    let handler = SecretsHandler::new(move || p.clone() as Arc<dyn SecretsProvider>);
    let scenario = serde_json::from_value(json!({
        "id": "secrets.extra", "category": "secrets", "steps": [
            {"op": "loadEnv", "args": {"mapping": {"GROWEXTRA_${run}_A": "m/a"}}, "expect": {"count": 1}},
            {"op": "list", "args": {"path": "m/"}, "expect": {"count": 2, "sorted": true}},
            {"op": "getString", "args": {"name": "m/none"}, "expect": {"null": true}},
            {"op": "get", "args": {"name": "m/bin"}, "expect": {"notNull": true}},
            {"op": "require", "args": {"name": "m/a"}, "expect": {"reveal": "va"}},
            {"op": "set", "args": {"name": "m/n"}, "expect": {"error": "VALIDATION"}},
            {"op": "get", "args": {}, "expect": {"error": "VALIDATION"}},
            {"op": "getMany", "args": {}, "expect": {"error": "VALIDATION"}},
            {"op": "nope", "expect": {"error": "UNSUPPORTED"}}
        ]
    }))
    .unwrap();
    let report = ConformanceRunner::new("/unused")
        .handler(handler)
        .run_scenarios(&[scenario])
        .await;
    report.assert_success();
